import re
import shutil
import subprocess
import tempfile
from pathlib import Path
from typing import Any, Optional

import pypdfium2
from docling_core.types.doc.document import ImageRef

from docling.backend.latex.engines.base import RenderEngine

_log = logging.getLogger(__name__)

# Matches a pdfTeX primitive assignment at the start of a line, e.g.
# ``\pdfoutput=1`` or ``\pdfpagewidth 210mm``. Tectonic uses the XeTeX
# engine, which does not implement these pdfTeX-only primitives, so such
# assignments make the compilation fail. Lines that merely *reference* or
# *test* a primitive (``\ifdefined\pdfoutput``, ``\ifnum\pdfoutput=1``) do
# not begin with the primitive control sequence and are left untouched.
_PDFTEX_ASSIGNMENT_RE = re.compile(r"^\s*\\pdf[a-zA-Z@]+\s*(=|[-+]?\.?\d)")

# Macros that reference files (relative to the source root) whose targets need
# to be staged next to the generated ``.tex`` file so Tectonic can find them
# without being granted access to the wider filesystem.
_FILE_REFERENCE_RE = re.compile(
    r"\\(?:includegraphics|input|include|lstinputlisting|import|subimport"
    r"|pgfimage|InputIfFileExists)\b\s*(?:\[[^\]]*\])?\s*\{([^}]*)\}"
)

# Extensions tried for graphics references that omit the file suffix.
_GRAPHICS_EXTENSIONS = (".pdf", ".png", ".jpg", ".jpeg", ".eps", ".svg")


class TectonicEngine(RenderEngine):
    """Render TikZ pictures into raster images using the Tectonic engine.

    The engine is deliberately conservative about filesystem access: it never
    passes a ``search-path`` to Tectonic and instead stages the local
    dependencies it can resolve inside ``source_root`` into an isolated working
    directory.
    """

    def __init__(
        self, timeout: float = 60.0, allow_shell_escape: bool = True
    ) -> None:
        self.timeout = timeout
        self.allow_shell_escape = allow_shell_escape

        binary = shutil.which("tectonic")
        if binary:
            self._is_available = True
            self.binary_path: Optional[Path] = Path(binary)
        else:
            self._is_available = False
            self.binary_path = None
            _log.warning(
                "Tectonic binary not found on PATH. Install Tectonic and make it "
                "available on PATH to enable rendering of TikZ pictures."
            )

    def is_available(self) -> bool:
        return self._is_available

    def render(
        self,
        tikz_code: str,
        preamble: str = "",
        source_root: Optional[Path] = None,
    ) -> Optional[Any]:
        if not self._is_available or self.binary_path is None:
            return None

        sanitized_preamble = self._sanitize_preamble_for_tectonic(preamble)
        tex_source = self._build_tex_source(sanitized_preamble, tikz_code)

        with tempfile.TemporaryDirectory(prefix="docling-tectonic-") as tmp:
            workdir = Path(tmp)
            tex_path = workdir / "tikz.tex"
            tex_path.write_text(tex_source, encoding="utf-8")

            if source_root is not None:
                self._stage_dependencies(
                    preamble + "\n" + tikz_code, source_root, workdir
                )

            cmd = [str(self.binary_path)]
            z_options = []
            if self.allow_shell_escape:
                z_options.append("shell-escape")
            # Never grant Tectonic an explicit search path: dependencies are
            # staged into the working directory instead.
            z_options = [
                opt for opt in z_options if not opt.startswith("search-path=")
            ]
            for opt in z_options:
                cmd += ["-Z", opt]
            cmd += ["--outdir", str(workdir), str(tex_path)]

            try:
                subprocess.run(
                    cmd,
                    cwd=str(workdir),
                    capture_output=True,
                    check=True,
                    timeout=self.timeout,
                )
            except subprocess.TimeoutExpired:
                _log.warning(
                    "Tectonic timed out after %ss while rendering a TikZ picture.",
                    self.timeout,
                )
                return None
            except subprocess.CalledProcessError as exc:
                stderr = ""
                if exc.stderr:
                    stderr = (
                        exc.stderr.decode("utf-8", errors="replace")
                        if isinstance(exc.stderr, bytes)
                        else str(exc.stderr)
                    )
                _log.warning(
                    "Tectonic failed to render a TikZ picture: %s", stderr.strip()
                )
                return None

            return self._pdf_to_image(tex_path.with_suffix(".pdf"))

    @staticmethod
    def _pdf_to_image(pdf_path: Path) -> Optional[ImageRef]:
        if not pdf_path.is_file():
            _log.warning("Tectonic produced no PDF output at %s", pdf_path)
            return None
        try:
            pdf = pypdfium2.PdfDocument(pdf_path)
            page = pdf[0]
            pil_image = page.render(scale=2).to_pil()
            page.close()
            pdf.close()
            return ImageRef.from_pil(image=pil_image, dpi=144)
        except Exception as exc:
            _log.warning("Failed to rasterize Tectonic PDF output: %s", exc)
            return None

    @staticmethod
    def _build_tex_source(sanitized_preamble: str, tikz_code: str) -> str:
        parts: list[str] = []
        if "\\documentclass" not in sanitized_preamble:
            parts.append("\\documentclass[tikz,border=2pt]{standalone}")
        if sanitized_preamble.strip():
            parts.append(sanitized_preamble)
        if (
            "\\usepackage{tikz}" not in sanitized_preamble
            and "{standalone}" not in sanitized_preamble
        ):
            parts.append("\\usepackage{tikz}")
        header = "\n".join(parts)
        return f"{header}\n\\begin{{document}}\n{tikz_code}\n\\end{{document}}\n"

    def _stage_dependencies(
        self, content: str, source_root: Path, workdir: Path
    ) -> None:
        root = source_root.resolve()
        for reference in self._extract_file_references(content):
            candidates = [reference]
            if not Path(reference).suffix:
                candidates += [reference + ext for ext in _GRAPHICS_EXTENSIONS]

            for candidate in candidates:
                src = source_root / candidate
                try:
                    resolved = src.resolve()
                except (OSError, ValueError):
                    continue
                if not resolved.is_relative_to(root):
                    _log.warning(
                        "Skipping TikZ dependency outside source root: %s",
                        candidate,
                    )
                    continue
                if not resolved.is_file():
                    continue

                dest = workdir / candidate
                dest.parent.mkdir(parents=True, exist_ok=True)
                shutil.copy2(resolved, dest)
                break

    @staticmethod
    def _extract_file_references(content: str) -> list[str]:
        references: list[str] = []
        for match in _FILE_REFERENCE_RE.finditer(content):
            argument = match.group(1).strip()
            if argument:
                references.append(argument)

